/*
 * t_v11.c -- host tests for n2a32_arm_media() (package V11).
 *
 * The encodings come from v11_enc.h, generated by gen_enc.py from llvm-mc; the
 * expected register/flag values are literals worked out from the ARMv7-A ARM ARM
 * pseudocode (A7.4 parallel add/sub, A8.8 instruction descriptions) and the Arm
 * A32/T32 instruction reference.  Every case also checks that the class function
 * leaves r15/next_pc/N/Z/C/V/thumb/in_it alone and that registers not named as
 * outputs keep their input value.
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "n2a32.h"
#include "v11_enc.h"

static int checks;
static int failures;
static struct n2a32_mem g_mem;

struct regv { int r; uint32_t v; };

#define R(r, v)  { (r), (v) }
#define IN(...)  ((const struct regv[]){ __VA_ARGS__, { -1, 0u } })
#define OUT(...) ((const struct regv[]){ __VA_ARGS__, { -1, 0u } })

/* "leave GE alone": the harness presets GE = 0b0101 and every case that does not
 * write GE expects exactly that value back. */
#define KEEP 5u

#define T1(nm, insn, a, want)           run_case((nm), (insn), IN(R(1, (a))), OUT(R(0, (want))), KEEP, KEEP, 0u, 0u)
#define T1G(nm, insn, a, want, ge)      run_case((nm), (insn), IN(R(1, (a))), OUT(R(0, (want))), KEEP, (ge), 0u, 0u)
#define T1Q(nm, insn, a, want, q)       run_case((nm), (insn), IN(R(1, (a))), OUT(R(0, (want))), KEEP, KEEP, 0u, (q))
#define T2(nm, insn, a, b, want)        run_case((nm), (insn), IN(R(1, (a)), R(2, (b))), OUT(R(0, (want))), KEEP, KEEP, 0u, 0u)
#define T2G(nm, insn, a, b, want, ge)   run_case((nm), (insn), IN(R(1, (a)), R(2, (b))), OUT(R(0, (want))), KEEP, (ge), 0u, 0u)
#define T2Q(nm, insn, a, b, want, q)    run_case((nm), (insn), IN(R(1, (a)), R(2, (b))), OUT(R(0, (want))), KEEP, KEEP, 0u, (q))
#define T3(nm, insn, a, b, c, want)     run_case((nm), (insn), IN(R(1, (a)), R(2, (b)), R(3, (c))), OUT(R(0, (want))), KEEP, KEEP, 0u, 0u)
#define T3Q(nm, insn, a, b, c, w, q)    run_case((nm), (insn), IN(R(1, (a)), R(2, (b)), R(3, (c))), OUT(R(0, (w))), KEEP, KEEP, 0u, (q))
/* long 64-bit accumulate: r0 = RdLo, r1 = RdHi, r2 = Rn, r3 = Rm */
#define TL(nm, insn, ilo, ihi, a, b, olo, ohi) \
	run_case((nm), (insn), IN(R(0, (ilo)), R(1, (ihi)), R(2, (a)), R(3, (b))), \
	         OUT(R(0, (olo)), R(1, (ohi))), KEEP, KEEP, 0u, 0u)

static uint32_t poison(unsigned i)
{
	return 0x51000000u + 0x01111111u * (uint32_t)i;
}

static void bad(const char *nm, const char *what, uint32_t got, uint32_t want)
{
	failures++;
	printf("FAIL %s: %s got %08x want %08x\n", nm, what, got, want);
}

static void cpu_fresh(struct n2a32_cpu *cpu)
{
	unsigned i;

	memset(cpu, 0, sizeof *cpu);
	cpu->mem = &g_mem;
	for (i = 0; i < 16; i++)
		cpu->r[i] = poison(i);
	cpu->r[13] = 0x00002000u;
	cpu->r[14] = 0x00003000u;
	cpu->r[15] = 0x00008000u;
	cpu->next_pc = 0x00008004u;
	cpu->n = 1;
	cpu->z = 1;
	cpu->cf = 0;
	cpu->v = 1;
	cpu->q = 0;
	cpu->ge = KEEP;
	cpu->thumb = 0;
	cpu->in_it = 0;
}

static void run_case(const char *nm, uint32_t insn, const struct regv *in,
                     const struct regv *out, unsigned gein, unsigned want_ge,
                     unsigned qin, unsigned want_q)
{
	struct n2a32_cpu cpu;
	uint32_t before[16];
	unsigned i, k;
	int rc;

	cpu_fresh(&cpu);
	for (k = 0; in[k].r >= 0; k++)
		cpu.r[in[k].r] = in[k].v;
	memcpy(before, cpu.r, sizeof before);
	cpu.ge = (uint8_t)(gein & 0xfu);
	cpu.q = (uint8_t)(qin & 1u);

	rc = n2a32_arm_media(&cpu, insn);
	checks++;
	if (rc != N2A32_OK) {
		failures++;
		printf("FAIL %s: rc=%d (expected N2A32_OK)\n", nm, rc);
		return;
	}
	for (i = 0; i < 16; i++) {
		uint32_t want = before[i];

		for (k = 0; out[k].r >= 0; k++)
			if ((unsigned)out[k].r == i)
				want = out[k].v;
		if (cpu.r[i] != want)
			bad(nm, "register", cpu.r[i], want);
	}
	if (cpu.next_pc != 0x00008004u)
		bad(nm, "next_pc", cpu.next_pc, 0x00008004u);
	if (cpu.r[15] != 0x00008000u)
		bad(nm, "r15", cpu.r[15], 0x00008000u);
	if (cpu.n != 1 || cpu.z != 1 || cpu.cf != 0 || cpu.v != 1) {
		failures++;
		printf("FAIL %s: NZCV changed (n=%u z=%u c=%u v=%u)\n",
		       nm, (unsigned)cpu.n, (unsigned)cpu.z, (unsigned)cpu.cf, (unsigned)cpu.v);
	}
	if (cpu.q != (uint8_t)(want_q & 1u)) {
		failures++;
		printf("FAIL %s: Q=%u want %u\n", nm, (unsigned)cpu.q, want_q & 1u);
	}
	if ((cpu.ge & 0xfu) != (want_ge & 0xfu)) {
		failures++;
		printf("FAIL %s: GE=%x want %x\n", nm, (unsigned)(cpu.ge & 0xfu), want_ge & 0xfu);
	}
	if (cpu.thumb != 0 || cpu.in_it != 0) {
		failures++;
		printf("FAIL %s: thumb/in_it changed\n", nm);
	}
}

static void expect_undef(const char *nm, uint32_t insn)
{
	struct n2a32_cpu cpu;
	uint32_t before[16];
	unsigned i;
	int rc;

	cpu_fresh(&cpu);
	memcpy(before, cpu.r, sizeof before);
	rc = n2a32_arm_media(&cpu, insn);
	checks++;
	if (rc != N2A32_UNDEF) {
		failures++;
		printf("FAIL %s: expected N2A32_UNDEF, got %d (%08x)\n", nm, rc, insn);
		return;
	}
	for (i = 0; i < 16; i++)
		if (cpu.r[i] != before[i]) {
			bad(nm, "register changed by a rejected encoding", cpu.r[i], before[i]);
			return;
		}
	if (cpu.next_pc != 0x00008004u || cpu.n != 1 || cpu.z != 1 || cpu.cf != 0 ||
	    cpu.v != 1 || cpu.q != 0 || (cpu.ge & 0xfu) != KEEP ||
	    cpu.thumb != 0 || cpu.in_it != 0) {
		failures++;
		printf("FAIL %s: state changed by a rejected encoding\n", nm);
	}
}

/* 200000 random words biased into the class's encoding space: the function must
 * return N2A32_OK or N2A32_UNDEF, must never crash, and an OK return must leave
 * the PC alone.  Deterministic LCG so a failure can be reproduced. */
static void sweep(void)
{
	uint32_t s = 0x12345678u;
	unsigned i;
	int bad_rc = 0, bad_pc = 0;

	for (i = 0; i < 200000u; i++) {
		struct n2a32_cpu cpu;
		uint32_t w, insn;
		int rc;

		s = s * 1664525u + 1013904223u;
		w = s;
		switch (i & 3u) {
		case 0: insn = (w & 0x0fffffffu) | 0x06000010u; break;  /* 0110 group */
		case 1: insn = (w & 0x0fffffffu) | 0x07000010u; break;  /* 0111 group */
		case 2: insn = (w & 0x0fffffffu) | 0x01000000u; break;  /* 0001 group */
		default: insn = w; break;                               /* anything */
		}
		cpu_fresh(&cpu);
		rc = n2a32_arm_media(&cpu, insn);
		if (rc != N2A32_OK && rc != N2A32_UNDEF) {
			bad_rc++;
			if (bad_rc < 4)
				printf("FAIL sweep: rc=%d for %08x\n", rc, insn);
		}
		if (rc == N2A32_OK && (cpu.next_pc != 0x00008004u || cpu.r[15] != 0x00008000u)) {
			bad_pc++;
			if (bad_pc < 4)
				printf("FAIL sweep: PC moved for %08x\n", insn);
		}
	}
	checks++;
	if (bad_rc || bad_pc) {
		failures++;
		printf("FAIL sweep: %d bad returns, %d PC changes in 200000 words\n", bad_rc, bad_pc);
	}
}

/* ------------------------------------------------------------------------------------ */
/* SXTB SXTH UXTB UXTH (+ ROR #8/16/24), SXTA* UXTA*, SXTB16 UXTB16 SXTA*16 UXTA*16      */
/* ------------------------------------------------------------------------------------ */
static void test_extend(void)
{
	/* SXTB: d = SignExtend(r1[7:0]) */
	T1("sxtb 0x7f", ENC_sxtb_r0_r1, 0x0000007fu, 0x0000007fu);
	T1("sxtb 0x80", ENC_sxtb_r0_r1, 0x00000080u, 0xffffff80u);
	T1("sxtb 0xff", ENC_sxtb_r0_r1, 0x000000ffu, 0xffffffffu);
	T1("sxtb 0", ENC_sxtb_r0_r1, 0x00000000u, 0x00000000u);
	T1("sxtb 0x78", ENC_sxtb_r0_r1, 0x12345678u, 0x00000078u);
	T1("sxtb 0x9c", ENC_sxtb_r0_r1, 0x0000009cu, 0xffffff9cu);

	/* SXTB, ROR #8: the rotation is applied before the byte is taken */
	T1("sxtb ror8 ff", ENC_sxtb_r0_r1_ror8, 0x0000ff00u, 0xffffffffu);
	T1("sxtb ror8 7f", ENC_sxtb_r0_r1_ror8, 0x00007f00u, 0x0000007fu);
	T1("sxtb ror8 80", ENC_sxtb_r0_r1_ror8, 0x12348000u, 0xffffff80u);
	T1("sxtb ror8 01", ENC_sxtb_r0_r1_ror8, 0x00000100u, 0x00000001u);
	T1("sxtb ror8 be", ENC_sxtb_r0_r1_ror8, 0xdeadbeefu, 0xffffffbeu);
	T1("sxtb ror8 9c", ENC_sxtb_r0_r1_ror8, 0x00009c00u, 0xffffff9cu);

	/* SXTB, ROR #16 and ROR #24 */
	T1("sxtb ror16 ff", ENC_sxtb_r0_r1_ror16, 0x00ff0000u, 0xffffffffu);
	T1("sxtb ror16 7f", ENC_sxtb_r0_r1_ror16, 0x007f0000u, 0x0000007fu);
	T1("sxtb ror16 ad", ENC_sxtb_r0_r1_ror16, 0xdeadbeefu, 0xffffffadu);
	T1("sxtb ror16 00", ENC_sxtb_r0_r1_ror16, 0x00000080u, 0x00000000u);
	T1("sxtb ror16 80", ENC_sxtb_r0_r1_ror16, 0x80000000u, 0x00000000u);
	T1("sxtb ror16 12", ENC_sxtb_r0_r1_ror16, 0x12000000u, 0x00000000u);
	T1("sxtb ror24 ff", ENC_sxtb_r0_r1_ror24, 0xff000000u, 0xffffffffu);
	T1("sxtb ror24 7f", ENC_sxtb_r0_r1_ror24, 0x7f000000u, 0x0000007fu);
	T1("sxtb ror24 80", ENC_sxtb_r0_r1_ror24, 0x80000000u, 0xffffff80u);
	T1("sxtb ror24 de", ENC_sxtb_r0_r1_ror24, 0xdeadbeefu, 0xffffffdeu);
	T1("sxtb ror24 00", ENC_sxtb_r0_r1_ror24, 0x00000000u, 0x00000000u);
	T1("sxtb ror24 01", ENC_sxtb_r0_r1_ror24, 0x01000000u, 0x00000001u);

	/* SXTH */
	T1("sxth 7fff", ENC_sxth_r0_r1, 0x00007fffu, 0x00007fffu);
	T1("sxth 8000", ENC_sxth_r0_r1, 0x00008000u, 0xffff8000u);
	T1("sxth ffff", ENC_sxth_r0_r1, 0x0000ffffu, 0xffffffffu);
	T1("sxth 5678", ENC_sxth_r0_r1, 0x12345678u, 0x00005678u);
	T1("sxth beef", ENC_sxth_r0_r1, 0xdeadbeefu, 0xffffbeefu);
	T1("sxth 0", ENC_sxth_r0_r1, 0x00000000u, 0x00000000u);
	/* SXTH ROR #8 takes bits[23:8] */
	T1("sxth ror8 ff00", ENC_sxth_r0_r1_ror8, 0x00ff0000u, 0xffffff00u);
	T1("sxth ror8 8000", ENC_sxth_r0_r1_ror8, 0x00800000u, 0xffff8000u);
	T1("sxth ror8 0100", ENC_sxth_r0_r1_ror8, 0x00010000u, 0x00000100u);
	T1("sxth ror8 adbe", ENC_sxth_r0_r1_ror8, 0xdeadbeefu, 0xffffadbeu);
	T1("sxth ror8 007f", ENC_sxth_r0_r1_ror8, 0x00007f00u, 0x0000007fu);
	T1("sxth ror8 ff00b", ENC_sxth_r0_r1_ror8, 0xff000000u, 0x00000000u);

	/* UXTB / UXTH */
	T1("uxtb ff", ENC_uxtb_r0_r1, 0x000000ffu, 0x000000ffu);
	T1("uxtb ff00", ENC_uxtb_r0_r1, 0xffffff00u, 0x00000000u);
	T1("uxtb ef", ENC_uxtb_r0_r1, 0xdeadbeefu, 0x000000efu);
	T1("uxtb 78", ENC_uxtb_r0_r1, 0x12345678u, 0x00000078u);
	T1("uxtb 0", ENC_uxtb_r0_r1, 0x00000000u, 0x00000000u);
	T1("uxtb 80", ENC_uxtb_r0_r1, 0x80000080u, 0x00000080u);
	T1("uxtb ror8 ff", ENC_uxtb_r0_r1_ror8, 0x0000ff00u, 0x000000ffu);
	T1("uxtb ror8 80", ENC_uxtb_r0_r1_ror8, 0x00008000u, 0x00000080u);
	T1("uxtb ror8 be", ENC_uxtb_r0_r1_ror8, 0xdeadbeefu, 0x000000beu);
	T1("uxtb ror8 01", ENC_uxtb_r0_r1_ror8, 0x00000100u, 0x00000001u);
	T1("uxtb ror8 ff2", ENC_uxtb_r0_r1_ror8, 0xffffffffu, 0x000000ffu);
	T1("uxtb ror8 0", ENC_uxtb_r0_r1_ror8, 0x00000000u, 0x00000000u);
	T1("uxtb ror16 ff", ENC_uxtb_r0_r1_ror16, 0x00ff0000u, 0x000000ffu);
	T1("uxtb ror16 ad", ENC_uxtb_r0_r1_ror16, 0xdeadbeefu, 0x000000adu);
	T1("uxtb ror16 42", ENC_uxtb_r0_r1_ror16, 0x00004200u, 0x00000000u);
	T1("uxtb ror16 00", ENC_uxtb_r0_r1_ror16, 0xff000000u, 0x00000000u);
	T1("uxtb ror16 80", ENC_uxtb_r0_r1_ror16, 0x00800000u, 0x00000080u);
	T1("uxtb ror16 56", ENC_uxtb_r0_r1_ror16, 0x12345678u, 0x00000034u);
	T1("uxtb ror24 ff", ENC_uxtb_r0_r1_ror24, 0xff000000u, 0x000000ffu);
	T1("uxtb ror24 7f", ENC_uxtb_r0_r1_ror24, 0x7f000000u, 0x0000007fu);
	T1("uxtb ror24 de", ENC_uxtb_r0_r1_ror24, 0xdeadbeefu, 0x000000deu);
	T1("uxtb ror24 00", ENC_uxtb_r0_r1_ror24, 0x00ff0000u, 0x00000000u);
	T1("uxtb ror24 80", ENC_uxtb_r0_r1_ror24, 0x80000000u, 0x00000080u);
	T1("uxtb ror24 01", ENC_uxtb_r0_r1_ror24, 0x01020304u, 0x00000001u);
	T1("uxth ffff", ENC_uxth_r0_r1, 0x0000ffffu, 0x0000ffffu);
	T1("uxth 0", ENC_uxth_r0_r1, 0xffff0000u, 0x00000000u);
	T1("uxth beef", ENC_uxth_r0_r1, 0xdeadbeefu, 0x0000beefu);
	T1("uxth 5678", ENC_uxth_r0_r1, 0x12345678u, 0x00005678u);
	T1("uxth 00", ENC_uxth_r0_r1, 0x00000000u, 0x00000000u);
	T1("uxth 8000", ENC_uxth_r0_r1, 0x80008000u, 0x00008000u);
	T1("uxth ror16 ffff", ENC_uxth_r0_r1_ror16, 0xffff0000u, 0x0000ffffu);
	T1("uxth ror16 1234", ENC_uxth_r0_r1_ror16, 0x12345678u, 0x00001234u);
	T1("uxth ror16 dead", ENC_uxth_r0_r1_ror16, 0xdeadbeefu, 0x0000deadu);
	T1("uxth ror16 00", ENC_uxth_r0_r1_ror16, 0x0000ffffu, 0x00000000u);
	T1("uxth ror16 8000", ENC_uxth_r0_r1_ror16, 0x80000000u, 0x00008000u);
	T1("uxth ror16 0001", ENC_uxth_r0_r1_ror16, 0x00010000u, 0x00000001u);
}

/* SXTA* / UXTA*: d = r1 + extend(rotate(r2)) */
static void test_extend_add(void)
{
	T2("sxtab 0x80", ENC_sxtab_r0_r1_r2, 0x00000000u, 0x00000080u, 0xffffff80u);
	T2("sxtab 1-1", ENC_sxtab_r0_r1_r2, 0x00000001u, 0x000000ffu, 0x00000000u);
	T2("sxtab max+1", ENC_sxtab_r0_r1_r2, 0x7fffffffu, 0x00000001u, 0x80000000u);
	T2("sxtab f0+10", ENC_sxtab_r0_r1_r2, 0xfffffff0u, 0x00000010u, 0x00000000u);
	T2("sxtab -100", ENC_sxtab_r0_r1_r2, 0x12345678u, 0x0000009cu, 0x12345614u);
	T2("sxtab +7f", ENC_sxtab_r0_r1_r2, 0xdeadbeefu, 0x0000007fu, 0xdeadbf6eu);
	T2("sxtab ror8 80", ENC_sxtab_r0_r1_r2_ror8, 0x00000000u, 0x00008000u, 0xffffff80u);
	T2("sxtab ror8 10-1", ENC_sxtab_r0_r1_r2_ror8, 0x00000010u, 0x0000ff00u, 0x0000000fu);
	T2("sxtab ror8 +56", ENC_sxtab_r0_r1_r2_ror8, 0xffffffffu, 0x12345678u, 0x00000055u);
	T2("sxtab ror8 +1", ENC_sxtab_r0_r1_r2_ror8, 0x00000000u, 0x00000100u, 0x00000001u);
	T2("sxtab ror8 -100", ENC_sxtab_r0_r1_r2_ror8, 0x80000000u, 0x00009c00u, 0x7fffff9cu);
	T2("sxtab ror8 +7f", ENC_sxtab_r0_r1_r2_ror8, 0x0000ffffu, 0x00007f00u, 0x0001007eu);
	T2("sxtah 8000", ENC_sxtah_r0_r1_r2, 0x00000000u, 0x00008000u, 0xffff8000u);
	T2("sxtah 1-1", ENC_sxtah_r0_r1_r2, 0x00000001u, 0x0000ffffu, 0x00000000u);
	T2("sxtah max+1", ENC_sxtah_r0_r1_r2, 0x7fffffffu, 0x00000001u, 0x80000000u);
	T2("sxtah +5678", ENC_sxtah_r0_r1_r2, 0x12340000u, 0x00005678u, 0x12345678u);
	T2("sxtah beef", ENC_sxtah_r0_r1_r2, 0x00000000u, 0xdeadbeefu, 0xffffbeefu);
	T2("sxtah -1+7fff", ENC_sxtah_r0_r1_r2, 0xffffffffu, 0x00007fffu, 0x00007ffeu);
	T2("sxtah ror16 8000", ENC_sxtah_r0_r1_r2_ror16, 0x00000000u, 0x80000000u, 0xffff8000u);
	T2("sxtah ror16 dead", ENC_sxtah_r0_r1_r2_ror16, 0x00000000u, 0xdeadbeefu, 0xffffdeadu);
	T2("sxtah ror16 +1", ENC_sxtah_r0_r1_r2_ror16, 0x00010000u, 0x00010000u, 0x00010001u);
	T2("sxtah ror16 -2", ENC_sxtah_r0_r1_r2_ror16, 0xffffffffu, 0xffff0000u, 0xfffffffeu);
	T2("sxtah ror16 +1b", ENC_sxtah_r0_r1_r2_ror16, 0x7fff0000u, 0x00010000u, 0x7fff0001u);
	T2("sxtah ror16 0", ENC_sxtah_r0_r1_r2_ror16, 0x00000000u, 0x0000ffffu, 0x00000000u);
	T2("uxtab ef", ENC_uxtab_r0_r1_r2, 0x00000000u, 0xdeadbeefu, 0x000000efu);
	T2("uxtab -256+ff", ENC_uxtab_r0_r1_r2, 0xffffff00u, 0x000000ffu, 0xffffffffu);
	T2("uxtab max+1", ENC_uxtab_r0_r1_r2, 0x7fffffffu, 0x00000001u, 0x80000000u);
	T2("uxtab +9c", ENC_uxtab_r0_r1_r2, 0x12345678u, 0x0000009cu, 0x12345714u);
	T2("uxtab -1+1", ENC_uxtab_r0_r1_r2, 0xffffffffu, 0x00000001u, 0x00000000u);
	T2("uxtab 0", ENC_uxtab_r0_r1_r2, 0x00000000u, 0x00000000u, 0x00000000u);
	T2("uxtab ror16 ff", ENC_uxtab_r0_r1_r2_ror16, 0x00000000u, 0x00ff0000u, 0x000000ffu);
	T2("uxtab ror16 ad", ENC_uxtab_r0_r1_r2_ror16, 0x00000000u, 0xdeadbeefu, 0x000000adu);
	T2("uxtab ror16 +1", ENC_uxtab_r0_r1_r2_ror16, 0x00000001u, 0x00000000u, 0x00000001u);
	T2("uxtab ror16 +1b", ENC_uxtab_r0_r1_r2_ror16, 0xffff0000u, 0x00000100u, 0xffff0000u);
	T2("uxtab ror16 max", ENC_uxtab_r0_r1_r2_ror16, 0x7fffffffu, 0x00ff0000u, 0x800000feu);
	T2("uxtab ror16 0", ENC_uxtab_r0_r1_r2_ror16, 0x00000000u, 0xff000000u, 0x00000000u);
	T2("uxtah beef", ENC_uxtah_r0_r1_r2, 0x00000000u, 0xdeadbeefu, 0x0000beefu);
	T2("uxtah -1+ffff", ENC_uxtah_r0_r1_r2, 0xffff0000u, 0x0000ffffu, 0xffffffffu);
	T2("uxtah max+1", ENC_uxtah_r0_r1_r2, 0x7fffffffu, 0x00000001u, 0x80000000u);
	T2("uxtah +ffff", ENC_uxtah_r0_r1_r2, 0x12345678u, 0x0000ffffu, 0x12355677u);
	T2("uxtah -1+1", ENC_uxtah_r0_r1_r2, 0xffffffffu, 0x00000001u, 0x00000000u);
	T2("uxtah 0", ENC_uxtah_r0_r1_r2, 0x00000000u, 0xffff0000u, 0x00000000u);

	/* SXTB16 / UXTB16 and their accumulating forms: the two halves are independent */
	T1("sxtb16 7f", ENC_sxtb16_r0_r1, 0x0000007fu, 0x0000007fu);
	T1("sxtb16 8080", ENC_sxtb16_r0_r1, 0x00008080u, 0x0000ff80u);
	T1("sxtb16 ffff", ENC_sxtb16_r0_r1, 0x00ff00ffu, 0xffffffffu);
	T1("sxtb16 5678", ENC_sxtb16_r0_r1, 0x12345678u, 0x00340078u);
	T1("sxtb16 adef", ENC_sxtb16_r0_r1, 0xdeadbeefu, 0xffadffefu);
	T1("sxtb16 0", ENC_sxtb16_r0_r1, 0x00000000u, 0x00000000u);
	T1("sxtb16 ror8 80", ENC_sxtb16_r0_r1_ror8, 0x00008000u, 0x0000ff80u);
	T1("sxtb16 ror8 80b", ENC_sxtb16_r0_r1_ror8, 0x80000000u, 0xff800000u);
	T1("sxtb16 ror8 ff", ENC_sxtb16_r0_r1_ror8, 0x000000ffu, 0x00000000u);
	T1("sxtb16 ror8 ff00", ENC_sxtb16_r0_r1_ror8, 0x0000ff00u, 0x0000ffffu);
	T1("sxtb16 ror8 5678", ENC_sxtb16_r0_r1_ror8, 0x12345678u, 0x00120056u);
	T1("sxtb16 ror8 be", ENC_sxtb16_r0_r1_ror8, 0xdeadbeefu, 0xffdeffbeu);
	T1("uxtb16 adef", ENC_uxtb16_r0_r1, 0xdeadbeefu, 0x00ad00efu);
	T1("uxtb16 ffff", ENC_uxtb16_r0_r1, 0xffffffffu, 0x00ff00ffu);
	T1("uxtb16 5678", ENC_uxtb16_r0_r1, 0x12345678u, 0x00340078u);
	T1("uxtb16 0", ENC_uxtb16_r0_r1, 0x00000000u, 0x00000000u);
	T1("uxtb16 ff00", ENC_uxtb16_r0_r1, 0x0000ff00u, 0x00000000u);
	T1("uxtb16 ff", ENC_uxtb16_r0_r1, 0x00ff0000u, 0x00ff0000u);
	T1("uxtb16 ror24 ff", ENC_uxtb16_r0_r1_ror24, 0xff000000u, 0x000000ffu);
	T1("uxtb16 ror24 beef", ENC_uxtb16_r0_r1_ror24, 0xdeadbeefu, 0x00be00deu);
	T1("uxtb16 ror24 ff2", ENC_uxtb16_r0_r1_ror24, 0x0000ff00u, 0x00ff0000u);
	T1("uxtb16 ror24 5678", ENC_uxtb16_r0_r1_ror24, 0x12345678u, 0x00560012u);
	T1("uxtb16 ror24 80", ENC_uxtb16_r0_r1_ror24, 0x80000000u, 0x00000080u);
	T1("uxtb16 ror24 ff00", ENC_uxtb16_r0_r1_ror24, 0x00ff00ffu, 0x00000000u);
	T2("sxtab16 80", ENC_sxtab16_r0_r1_r2, 0x00000000u, 0x00000080u, 0x0000ff80u);
	T2("sxtab16 1-1", ENC_sxtab16_r0_r1_r2, 0x00010001u, 0x000000ffu, 0x00010000u);
	T2("sxtab16 7fff", ENC_sxtab16_r0_r1_r2, 0x7fff7fffu, 0x00000001u, 0x7fff8000u);
	T2("sxtab16 8000", ENC_sxtab16_r0_r1_r2, 0x80008000u, 0x00008000u, 0x80008000u);
	T2("sxtab16 -1-1", ENC_sxtab16_r0_r1_r2, 0xffffffffu, 0x00ff00ffu, 0xfffefffeu);
	T2("sxtab16 -100", ENC_sxtab16_r0_r1_r2, 0x12345678u, 0x0000009cu, 0x12345614u);
	T2("sxtab16 ror8 80", ENC_sxtab16_r0_r1_r2_ror8, 0x00000000u, 0x00008000u, 0x0000ff80u);
	T2("sxtab16 ror8 80b", ENC_sxtab16_r0_r1_r2_ror8, 0x00000000u, 0x80000000u, 0xff800000u);
	T2("sxtab16 ror8 1-1", ENC_sxtab16_r0_r1_r2_ror8, 0x00000001u, 0x0000ff00u, 0x00000000u);
	T2("sxtab16 ror8 +56", ENC_sxtab16_r0_r1_r2_ror8, 0x00000000u, 0x12345678u, 0x00120056u);
	T2("sxtab16 ror8 -66", ENC_sxtab16_r0_r1_r2_ror8, 0xffffffffu, 0xdeadbeefu, 0xffddffbdu);
	T2("sxtab16 ror8 -99", ENC_sxtab16_r0_r1_r2_ror8, 0x00010001u, 0x00009c00u, 0x0001ff9du);
	T2("uxtab16 adef", ENC_uxtab16_r0_r1_r2, 0x00000000u, 0xdeadbeefu, 0x00ad00efu);
	T2("uxtab16 1+ff", ENC_uxtab16_r0_r1_r2, 0x00010001u, 0x0000ffffu, 0x00010100u);
	T2("uxtab16 -1+1", ENC_uxtab16_r0_r1_r2, 0xffffffffu, 0x00000001u, 0xffff0000u);
	T2("uxtab16 5678", ENC_uxtab16_r0_r1_r2, 0x00000000u, 0x12345678u, 0x00340078u);
	T2("uxtab16 8000", ENC_uxtab16_r0_r1_r2, 0x80008000u, 0x000000ffu, 0x800080ffu);
	T2("uxtab16 0", ENC_uxtab16_r0_r1_r2, 0x00000000u, 0x00000000u, 0x00000000u);

	/* SP (r13) is a legal A32 operand; r15 is not (checked as UNDEF later) */
	run_case("sxtb sp source", ENC_sxtb_r0_r13, IN(R(13, 0x00002080u)), OUT(R(0, 0xffffff80u)), KEEP, KEEP, 0u, 0u);
	/* Rd = r13: replace the Rd field of the llvm-mc encoding (sp is legal in A32) */
	run_case("sxtb sp dest", (ENC_sxtb_r0_r1 & ~0x0000f000u) | 0x0000d000u,
	         IN(R(1, 0x00000080u)), OUT(R(13, 0xffffff80u)), KEEP, KEEP, 0u, 0u);
}

/* ------------------------------------------------------------------------------------ */
/* UBFX SBFX BFI BFC                                                                    */
/* ------------------------------------------------------------------------------------ */
static void test_bitfield(void)
{
	/* UBFX r0, r1, #4, #8: bits [11:4] zero-extended */
	T1("ubfx 4,8 ffff", ENC_ubfx_r0_r1_4_8, 0xffffffffu, 0x000000ffu);
	T1("ubfx 4,8 0", ENC_ubfx_r0_r1_4_8, 0x00000000u, 0x00000000u);
	T1("ubfx 4,8 12345678", ENC_ubfx_r0_r1_4_8, 0x12345678u, 0x00000067u);
	T1("ubfx 4,8 f0", ENC_ubfx_r0_r1_4_8, 0x00000f00u, 0x000000f0u);
	T1("ubfx 4,8 lsb-only", ENC_ubfx_r0_r1_4_8, 0x0000000fu, 0x00000000u);
	T1("ubfx 4,8 80000000", ENC_ubfx_r0_r1_4_8, 0x80000000u, 0x00000000u);
	T1("ubfx 0,1 1", ENC_ubfx_r0_r1_0_1, 0x00000001u, 0x00000001u);
	T1("ubfx 0,1 2", ENC_ubfx_r0_r1_0_1, 0x00000002u, 0x00000000u);
	T1("ubfx 0,1 ffffffff", ENC_ubfx_r0_r1_0_1, 0xffffffffu, 0x00000001u);
	T1("ubfx 0,1 0", ENC_ubfx_r0_r1_0_1, 0x00000000u, 0x00000000u);
	T1("ubfx 0,1 80000000", ENC_ubfx_r0_r1_0_1, 0x80000000u, 0x00000000u);
	T1("ubfx 0,1 7fffffff", ENC_ubfx_r0_r1_0_1, 0x7fffffffu, 0x00000001u);
	T1("ubfx 31,1 80000000", ENC_ubfx_r0_r1_31_1, 0x80000000u, 0x00000001u);
	T1("ubfx 31,1 7fffffff", ENC_ubfx_r0_r1_31_1, 0x7fffffffu, 0x00000000u);
	T1("ubfx 31,1 ffffffff", ENC_ubfx_r0_r1_31_1, 0xffffffffu, 0x00000001u);
	T1("ubfx 31,1 0", ENC_ubfx_r0_r1_31_1, 0x00000000u, 0x00000000u);
	T1("ubfx 31,1 40000000", ENC_ubfx_r0_r1_31_1, 0x40000000u, 0x00000000u);
	T1("ubfx 31,1 c0000000", ENC_ubfx_r0_r1_31_1, 0xc0000000u, 0x00000001u);
	/* field placement: UBFX r5, r6, #3, #5 */
	run_case("ubfx r5,r6 3,5", ENC_ubfx_r5_r6_3_5, IN(R(6, 0xffffffffu)), OUT(R(5, 0x0000001fu)), KEEP, KEEP, 0u, 0u);

	/* SBFX: the extracted field is sign-extended */
	T1("sbfx 0,32 ffffffff", ENC_sbfx_r0_r1_0_32, 0xffffffffu, 0xffffffffu);
	T1("sbfx 0,32 80000000", ENC_sbfx_r0_r1_0_32, 0x80000000u, 0x80000000u);
	T1("sbfx 0,32 7fffffff", ENC_sbfx_r0_r1_0_32, 0x7fffffffu, 0x7fffffffu);
	T1("sbfx 0,32 0", ENC_sbfx_r0_r1_0_32, 0x00000000u, 0x00000000u);
	T1("sbfx 0,32 12345678", ENC_sbfx_r0_r1_0_32, 0x12345678u, 0x12345678u);
	T1("sbfx 0,32 1", ENC_sbfx_r0_r1_0_32, 0x00000001u, 0x00000001u);
	T1("sbfx 7,9 ffff", ENC_sbfx_r0_r1_7_9, 0xffffffffu, 0xffffffffu);
	T1("sbfx 7,9 0", ENC_sbfx_r0_r1_7_9, 0x00000000u, 0x00000000u);
	T1("sbfx 7,9 0x80", ENC_sbfx_r0_r1_7_9, 0x00004000u, 0x00000080u);
	T1("sbfx 7,9 -128", ENC_sbfx_r0_r1_7_9, 0x00004000u, 0x00000080u);
	T1("sbfx 7,9 +255", ENC_sbfx_r0_r1_7_9, 0x00007f80u, 0x000000ffu);
	T1("sbfx 7,9 0x100", ENC_sbfx_r0_r1_7_9, 0x00008000u, 0xffffff00u);
	T1("sbfx 31,1 80000000", ENC_sbfx_r0_r1_31_1, 0x80000000u, 0xffffffffu);
	T1("sbfx 31,1 0", ENC_sbfx_r0_r1_31_1, 0x00000000u, 0x00000000u);
	T1("sbfx 31,1 7fffffff", ENC_sbfx_r0_r1_31_1, 0x7fffffffu, 0x00000000u);
	T1("sbfx 31,1 ffffffff", ENC_sbfx_r0_r1_31_1, 0xffffffffu, 0xffffffffu);
	T1("sbfx 31,1 40000000", ENC_sbfx_r0_r1_31_1, 0x40000000u, 0x00000000u);
	T1("sbfx 31,1 c0000000", ENC_sbfx_r0_r1_31_1, 0xc0000000u, 0xffffffffu);

	/* BFI: bits from r1 replace bits of the *existing* value of r0 */
#define BFI(nm, insn, d, s, want) \
	run_case((nm), (insn), IN(R(0, (d)), R(1, (s))), OUT(R(0, (want))), KEEP, KEEP, 0u, 0u)
	BFI("bfi 4,8 a", ENC_bfi_r0_r1_4_8, 0x00000000u, 0xffffffffu, 0x00000ff0u);
	BFI("bfi 4,8 b", ENC_bfi_r0_r1_4_8, 0xffffffffu, 0x00000000u, 0xfffff00fu);
	BFI("bfi 4,8 c", ENC_bfi_r0_r1_4_8, 0x12345678u, 0x000000abu, 0x12345ab8u);
	BFI("bfi 4,8 d", ENC_bfi_r0_r1_4_8, 0x00000ab0u, 0x000000abu, 0x00000ab0u);
	BFI("bfi 4,8 e", ENC_bfi_r0_r1_4_8, 0x00000000u, 0x0000ffffu, 0x00000ff0u);
	BFI("bfi 4,8 f", ENC_bfi_r0_r1_4_8, 0xffffffffu, 0x12345678u, 0xfffff78fu);
	BFI("bfi 0,32 a", ENC_bfi_r0_r1_0_32, 0xdeadbeefu, 0x12345678u, 0x12345678u);
	BFI("bfi 0,32 b", ENC_bfi_r0_r1_0_32, 0x00000000u, 0xffffffffu, 0xffffffffu);
	BFI("bfi 0,32 c", ENC_bfi_r0_r1_0_32, 0xffffffffu, 0x00000000u, 0x00000000u);
	BFI("bfi 0,32 d", ENC_bfi_r0_r1_0_32, 0x11111111u, 0x22222222u, 0x22222222u);
	BFI("bfi 0,32 e", ENC_bfi_r0_r1_0_32, 0x0f0f0f0fu, 0xf0f0f0f0u, 0xf0f0f0f0u);
	BFI("bfi 0,32 f", ENC_bfi_r0_r1_0_32, 0x00000001u, 0x80000000u, 0x80000000u);
	BFI("bfi 31,1 a", ENC_bfi_r0_r1_31_1, 0x00000000u, 0x00000001u, 0x80000000u);
	BFI("bfi 31,1 b", ENC_bfi_r0_r1_31_1, 0xffffffffu, 0x00000000u, 0x7fffffffu);
	BFI("bfi 31,1 c", ENC_bfi_r0_r1_31_1, 0x12345678u, 0xffffffffu, 0x92345678u);
	BFI("bfi 31,1 d", ENC_bfi_r0_r1_31_1, 0x92345678u, 0x00000000u, 0x12345678u);
	BFI("bfi 31,1 e", ENC_bfi_r0_r1_31_1, 0x00000000u, 0xfffffffeu, 0x00000000u);
	BFI("bfi 31,1 f", ENC_bfi_r0_r1_31_1, 0x00000000u, 0xffffffffu, 0x80000000u);
	/* BFC: clear bits [lsb, msb] of r0 (no source register: Rn field = 1111) */
#define BFC(nm, insn, d, want) \
	run_case((nm), (insn), IN(R(0, (d))), OUT(R(0, (want))), KEEP, KEEP, 0u, 0u)
	BFC("bfc 4,8 a", ENC_bfc_r0_4_8, 0xffffffffu, 0xfffff00fu);
	BFC("bfc 4,8 b", ENC_bfc_r0_4_8, 0x00000000u, 0x00000000u);
	BFC("bfc 4,8 c", ENC_bfc_r0_4_8, 0x12345ab8u, 0x12345008u);
	BFC("bfc 4,8 d", ENC_bfc_r0_4_8, 0x00000ff0u, 0x00000000u);
	BFC("bfc 4,8 e", ENC_bfc_r0_4_8, 0x0000000fu, 0x0000000fu);
	BFC("bfc 4,8 f", ENC_bfc_r0_4_8, 0x80000000u, 0x80000000u);
	BFC("bfc 31,1 a", ENC_bfc_r0_31_1, 0xffffffffu, 0x7fffffffu);
	BFC("bfc 31,1 b", ENC_bfc_r0_31_1, 0x00000000u, 0x00000000u);
	BFC("bfc 31,1 c", ENC_bfc_r0_31_1, 0x7fffffffu, 0x7fffffffu);
	BFC("bfc 31,1 d", ENC_bfc_r0_31_1, 0x80000000u, 0x00000000u);
	BFC("bfc 31,1 e", ENC_bfc_r0_31_1, 0xdeadbeefu, 0x5eadbeefu);
	BFC("bfc 31,1 f", ENC_bfc_r0_31_1, 0x00000001u, 0x00000001u);
	BFC("bfc 0,32 a", ENC_bfc_r0_0_32, 0xffffffffu, 0x00000000u);
	BFC("bfc 0,32 b", ENC_bfc_r0_0_32, 0x00000000u, 0x00000000u);
	BFC("bfc 0,32 c", ENC_bfc_r0_0_32, 0xdeadbeefu, 0x00000000u);
	BFC("bfc 0,32 d", ENC_bfc_r0_0_32, 0x12345678u, 0x00000000u);
	BFC("bfc 0,32 e", ENC_bfc_r0_0_32, 0x80000000u, 0x00000000u);
	BFC("bfc 0,32 f", ENC_bfc_r0_0_32, 0x7fffffffu, 0x00000000u);
	/* field placement: BFI r5, r6, #7, #9 -> r5[15:7] = r6[8:0] */
	run_case("bfi r5,r6 7,9", ENC_bfi_r5_r6_7_9, IN(R(5, 0x00000000u), R(6, 0xffffffffu)),
	         OUT(R(5, 0x0000ff80u)), KEEP, KEEP, 0u, 0u);

}

/* ------------------------------------------------------------------------------------ */
/* REV REV16 REVSH RBIT                                                                 */
/* ------------------------------------------------------------------------------------ */
static void test_rev(void)
{
	T1("rev 12345678", ENC_rev_r0_r1, 0x12345678u, 0x78563412u);
	T1("rev 0", ENC_rev_r0_r1, 0x00000000u, 0x00000000u);
	T1("rev ffffffff", ENC_rev_r0_r1, 0xffffffffu, 0xffffffffu);
	T1("rev deadbeef", ENC_rev_r0_r1, 0xdeadbeefu, 0xefbeaddeu);
	T1("rev 000000ff", ENC_rev_r0_r1, 0x000000ffu, 0xff000000u);
	T1("rev 80000000", ENC_rev_r0_r1, 0x80000000u, 0x00000080u);
	T1("rev16 12345678", ENC_rev16_r0_r1, 0x12345678u, 0x34127856u);
	T1("rev16 0", ENC_rev16_r0_r1, 0x00000000u, 0x00000000u);
	T1("rev16 ffff", ENC_rev16_r0_r1, 0xffffffffu, 0xffffffffu);
	T1("rev16 dead", ENC_rev16_r0_r1, 0xdeadbeefu, 0xaddeefbeu);
	T1("rev16 abcd", ENC_rev16_r0_r1, 0x0000abcdu, 0x0000cdabu);
	T1("rev16 00ff", ENC_rev16_r0_r1, 0x00ff00ffu, 0xff00ff00u);
	T1("revsh 1234", ENC_revsh_r0_r1, 0x00001234u, 0x00003412u);
	T1("revsh 0080", ENC_revsh_r0_r1, 0x00000080u, 0xffff8000u);
	T1("revsh 8000", ENC_revsh_r0_r1, 0x00008000u, 0x00000080u);
	T1("revsh 12345678", ENC_revsh_r0_r1, 0x12345678u, 0x00007856u);
	T1("revsh ffff", ENC_revsh_r0_r1, 0x0000ffffu, 0xffffffffu);
	T1("revsh 0", ENC_revsh_r0_r1, 0x00000000u, 0x00000000u);
	T1("rbit 0", ENC_rbit_r0_r1, 0x00000000u, 0x00000000u);
	T1("rbit ffffffff", ENC_rbit_r0_r1, 0xffffffffu, 0xffffffffu);
	T1("rbit 1", ENC_rbit_r0_r1, 0x00000001u, 0x80000000u);
	T1("rbit 80000000", ENC_rbit_r0_r1, 0x80000000u, 0x00000001u);
	T1("rbit 12345678", ENC_rbit_r0_r1, 0x12345678u, 0x1e6a2c48u);
	T1("rbit deadbeef", ENC_rbit_r0_r1, 0xdeadbeefu, 0xf77db57bu);
	/* field placement: REV r5, r6 */
	run_case("rev r5,r6", ENC_rev_r5_r6, IN(R(6, 0x12345678u)), OUT(R(5, 0x78563412u)), KEEP, KEEP, 0u, 0u);
}

/* ------------------------------------------------------------------------------------ */
/* SSAT USAT (LSL/ASR shift), SSAT16 USAT16                                             */
/* ------------------------------------------------------------------------------------ */
static void test_sat(void)
{
	/* SSAT r0, #1, r1: signed range [-1, 0] after LSL #0 */
	T1Q("ssat #1 0", ENC_ssat_r0_1_r1, 0x00000000u, 0x00000000u, 0);
	T1Q("ssat #1 -1", ENC_ssat_r0_1_r1, 0xffffffffu, 0xffffffffu, 0);
	T1Q("ssat #1 5", ENC_ssat_r0_1_r1, 0x00000005u, 0x00000000u, 1);
	T1Q("ssat #1 -5", ENC_ssat_r0_1_r1, 0xfffffffbu, 0xffffffffu, 1);
	T1Q("ssat #1 max", ENC_ssat_r0_1_r1, 0x7fffffffu, 0x00000000u, 1);
	T1Q("ssat #1 min", ENC_ssat_r0_1_r1, 0x80000000u, 0xffffffffu, 1);
	/* SSAT r0, #16, r1: signed range [-32768, 32767] */
	T1Q("ssat #16 32767", ENC_ssat_r0_16_r1, 0x00007fffu, 0x00007fffu, 0);
	T1Q("ssat #16 32768", ENC_ssat_r0_16_r1, 0x00008000u, 0x00007fffu, 1);
	T1Q("ssat #16 -32768", ENC_ssat_r0_16_r1, 0xffff8000u, 0xffff8000u, 0);
	T1Q("ssat #16 -32769", ENC_ssat_r0_16_r1, 0xffff7fffu, 0xffff8000u, 1);
	T1Q("ssat #16 0", ENC_ssat_r0_16_r1, 0x00000000u, 0x00000000u, 0);
	T1Q("ssat #16 -1", ENC_ssat_r0_16_r1, 0xffffffffu, 0xffffffffu, 0);
	/* SSAT r0, #32, r1: no value saturates */
	T1Q("ssat #32 7fffffff", ENC_ssat_r0_32_r1, 0x7fffffffu, 0x7fffffffu, 0);
	T1Q("ssat #32 80000000", ENC_ssat_r0_32_r1, 0x80000000u, 0x80000000u, 0);
	T1Q("ssat #32 ffffffff", ENC_ssat_r0_32_r1, 0xffffffffu, 0xffffffffu, 0);
	T1Q("ssat #32 0", ENC_ssat_r0_32_r1, 0x00000000u, 0x00000000u, 0);
	T1Q("ssat #32 1", ENC_ssat_r0_32_r1, 0x00000001u, 0x00000001u, 0);
	T1Q("ssat #32 deadbeef", ENC_ssat_r0_32_r1, 0xdeadbeefu, 0xdeadbeefu, 0);
	/* SSAT r0, #16, r1, LSL #5: r1 << 5 then saturate */
	T1Q("ssat lsl5 0", ENC_ssat_r0_16_r1_lsl5, 0x00000000u, 0x00000000u, 0);
	T1Q("ssat lsl5 1", ENC_ssat_r0_16_r1_lsl5, 0x00000001u, 0x00000020u, 0);
	T1Q("ssat lsl5 0x400", ENC_ssat_r0_16_r1_lsl5, 0x00000400u, 0x00007fffu, 1);
	T1Q("ssat lsl5 -1", ENC_ssat_r0_16_r1_lsl5, 0xffffffffu, 0xffffffe0u, 0);
	T1Q("ssat lsl5 -0x400", ENC_ssat_r0_16_r1_lsl5, 0xfffffc00u, 0xffff8000u, 0);
	T1Q("ssat lsl5 0x7ff", ENC_ssat_r0_16_r1_lsl5, 0x000007ffu, 0x00007fffu, 1);
	/* SSAT r0, #16, r1, ASR #3 */
	T1Q("ssat asr3 0x80000", ENC_ssat_r0_16_r1_asr3, 0x00080000u, 0x00007fffu, 1);
	T1Q("ssat asr3 -1", ENC_ssat_r0_16_r1_asr3, 0xffffffffu, 0xffffffffu, 0);
	T1Q("ssat asr3 0xfffffff8", ENC_ssat_r0_16_r1_asr3, 0xfffffff8u, 0xffffffffu, 0);
	T1Q("ssat asr3 0x80000000", ENC_ssat_r0_16_r1_asr3, 0x80000000u, 0xffff8000u, 1);
	T1Q("ssat asr3 0x7fffffff", ENC_ssat_r0_16_r1_asr3, 0x7fffffffu, 0x00007fffu, 1);
	T1Q("ssat asr3 0x40000", ENC_ssat_r0_16_r1_asr3, 0x00040000u, 0x00007fffu, 1);
	/* SSAT r0, #16, r1, ASR #32 */
	T1Q("ssat asr32 0", ENC_ssat_r0_16_r1_asr32, 0x00000000u, 0x00000000u, 0);
	T1Q("ssat asr32 -1", ENC_ssat_r0_16_r1_asr32, 0xffffffffu, 0xffffffffu, 0);
	T1Q("ssat asr32 7fffffff", ENC_ssat_r0_16_r1_asr32, 0x7fffffffu, 0x00000000u, 0);
	T1Q("ssat asr32 80000000", ENC_ssat_r0_16_r1_asr32, 0x80000000u, 0xffffffffu, 0);
	T1Q("ssat asr32 1", ENC_ssat_r0_16_r1_asr32, 0x00000001u, 0x00000000u, 0);
	T1Q("ssat asr32 80000001", ENC_ssat_r0_16_r1_asr32, 0x80000001u, 0xffffffffu, 0);
	/* SSAT r5, #8, r6: [-128, 127] */
	run_case("ssat r5,#8,r6 200", ENC_ssat_r5_8_r6, IN(R(6, 0x000000c8u)), OUT(R(5, 0x0000007fu)), KEEP, KEEP, 0u, 1u);
	run_case("ssat r5,#8,r6 -200", ENC_ssat_r5_8_r6, IN(R(6, 0xffffff38u)), OUT(R(5, 0xffffff80u)), KEEP, KEEP, 0u, 1u);
	run_case("ssat r5,#8,r6 127", ENC_ssat_r5_8_r6, IN(R(6, 0x0000007fu)), OUT(R(5, 0x0000007fu)), KEEP, KEEP, 0u, 0u);
	run_case("ssat r5,#8,r6 -128", ENC_ssat_r5_8_r6, IN(R(6, 0xffffff80u)), OUT(R(5, 0xffffff80u)), KEEP, KEEP, 0u, 0u);
	run_case("ssat r5,#8,r6 0", ENC_ssat_r5_8_r6, IN(R(6, 0x00000000u)), OUT(R(5, 0x00000000u)), KEEP, KEEP, 0u, 0u);
	run_case("ssat r5,#8,r6 1", ENC_ssat_r5_8_r6, IN(R(6, 0x00000001u)), OUT(R(5, 0x00000001u)), KEEP, KEEP, 0u, 0u);

	/* USAT r0, #0, r1: range [0, 0] */
	T1Q("usat #0 0", ENC_usat_r0_0_r1, 0x00000000u, 0x00000000u, 0);
	T1Q("usat #0 1", ENC_usat_r0_0_r1, 0x00000001u, 0x00000000u, 1);
	T1Q("usat #0 -1", ENC_usat_r0_0_r1, 0xffffffffu, 0x00000000u, 1);
	T1Q("usat #0 7fffffff", ENC_usat_r0_0_r1, 0x7fffffffu, 0x00000000u, 1);
	T1Q("usat #0 80000000", ENC_usat_r0_0_r1, 0x80000000u, 0x00000000u, 1);
	T1Q("usat #0 4", ENC_usat_r0_0_r1, 0x00000004u, 0x00000000u, 1);
	/* USAT r0, #8, r1: range [0, 255] */
	T1Q("usat #8 0", ENC_usat_r0_8_r1, 0x00000000u, 0x00000000u, 0);
	T1Q("usat #8 255", ENC_usat_r0_8_r1, 0x000000ffu, 0x000000ffu, 0);
	T1Q("usat #8 256", ENC_usat_r0_8_r1, 0x00000100u, 0x000000ffu, 1);
	T1Q("usat #8 -1", ENC_usat_r0_8_r1, 0xffffffffu, 0x00000000u, 1);
	T1Q("usat #8 -256", ENC_usat_r0_8_r1, 0xffffff00u, 0x00000000u, 1);
	T1Q("usat #8 7fffffff", ENC_usat_r0_8_r1, 0x7fffffffu, 0x000000ffu, 1);
	/* USAT r0, #31, r1: range [0, 2^31-1] */
	T1Q("usat #31 7fffffff", ENC_usat_r0_31_r1, 0x7fffffffu, 0x7fffffffu, 0);
	T1Q("usat #31 80000000", ENC_usat_r0_31_r1, 0x80000000u, 0x00000000u, 1);
	T1Q("usat #31 ffffffff", ENC_usat_r0_31_r1, 0xffffffffu, 0x00000000u, 1);
	T1Q("usat #31 0", ENC_usat_r0_31_r1, 0x00000000u, 0x00000000u, 0);
	T1Q("usat #31 1", ENC_usat_r0_31_r1, 0x00000001u, 0x00000001u, 0);
	T1Q("usat #31 7ffffffe", ENC_usat_r0_31_r1, 0x7ffffffeu, 0x7ffffffeu, 0);
	/* USAT r0, #8, r1, LSL #4 / ASR #2 / ASR #32 */
	T1Q("usat lsl4 0", ENC_usat_r0_8_r1_lsl4, 0x00000000u, 0x00000000u, 0);
	T1Q("usat lsl4 15", ENC_usat_r0_8_r1_lsl4, 0x0000000fu, 0x000000f0u, 0);
	T1Q("usat lsl4 16", ENC_usat_r0_8_r1_lsl4, 0x00000010u, 0x000000ffu, 1);
	T1Q("usat lsl4 -1", ENC_usat_r0_8_r1_lsl4, 0xffffffffu, 0x00000000u, 1);
	T1Q("usat lsl4 0x10000000", ENC_usat_r0_8_r1_lsl4, 0x10000000u, 0x00000000u, 0);
	T1Q("usat lsl4 0x08000000", ENC_usat_r0_8_r1_lsl4, 0x08000000u, 0x00000000u, 1);
	T1Q("usat asr2 0", ENC_usat_r0_8_r1_asr2, 0x00000000u, 0x00000000u, 0);
	T1Q("usat asr2 1023", ENC_usat_r0_8_r1_asr2, 0x000003ffu, 0x000000ffu, 0);
	T1Q("usat asr2 1024", ENC_usat_r0_8_r1_asr2, 0x00000400u, 0x000000ffu, 1);
	T1Q("usat asr2 -4", ENC_usat_r0_8_r1_asr2, 0xfffffffcu, 0x00000000u, 1);
	T1Q("usat asr2 -1", ENC_usat_r0_8_r1_asr2, 0xffffffffu, 0x00000000u, 1);
	T1Q("usat asr2 0x80000000", ENC_usat_r0_8_r1_asr2, 0x80000000u, 0x00000000u, 1);
	T1Q("usat asr32 0", ENC_usat_r0_8_r1_asr32, 0x00000000u, 0x00000000u, 0);
	T1Q("usat asr32 1", ENC_usat_r0_8_r1_asr32, 0x00000001u, 0x00000000u, 0);
	T1Q("usat asr32 -1", ENC_usat_r0_8_r1_asr32, 0xffffffffu, 0x00000000u, 1);
	T1Q("usat asr32 7fffffff", ENC_usat_r0_8_r1_asr32, 0x7fffffffu, 0x00000000u, 0);
	T1Q("usat asr32 80000000", ENC_usat_r0_8_r1_asr32, 0x80000000u, 0x00000000u, 1);
	T1Q("usat asr32 2", ENC_usat_r0_8_r1_asr32, 0x00000002u, 0x00000000u, 0);

	/* SSAT16 r0, #1, r1: each halfword to [-1, 0] */
	T1Q("ssat16 #1 0", ENC_ssat16_r0_1_r1, 0x00000000u, 0x00000000u, 0);
	T1Q("ssat16 #1 -1-1", ENC_ssat16_r0_1_r1, 0xffffffffu, 0xffffffffu, 0);
	T1Q("ssat16 #1 1", ENC_ssat16_r0_1_r1, 0x00000001u, 0x00000000u, 1);
	T1Q("ssat16 #1 lo", ENC_ssat16_r0_1_r1, 0x00000005u, 0x00000000u, 1);
	T1Q("ssat16 #1 hi", ENC_ssat16_r0_1_r1, 0x00050000u, 0x00000000u, 1);
	T1Q("ssat16 #1 -5", ENC_ssat16_r0_1_r1, 0x0000fffbu, 0x0000ffffu, 1);
	/* SSAT16 r0, #16, r1: no saturation possible */
	T1Q("ssat16 #16 8000", ENC_ssat16_r0_16_r1, 0x00008000u, 0x00008000u, 0);
	T1Q("ssat16 #16 7fff", ENC_ssat16_r0_16_r1, 0x00007fffu, 0x00007fffu, 0);
	T1Q("ssat16 #16 ffff", ENC_ssat16_r0_16_r1, 0x0000ffffu, 0x0000ffffu, 0);
	T1Q("ssat16 #16 mix", ENC_ssat16_r0_16_r1, 0x80007fffu, 0x80007fffu, 0);
	T1Q("ssat16 #16 0", ENC_ssat16_r0_16_r1, 0x00000000u, 0x00000000u, 0);
	T1Q("ssat16 #16 -1", ENC_ssat16_r0_16_r1, 0xffffffffu, 0xffffffffu, 0);
	run_case("ssat16 r5,#8,r6", ENC_ssat16_r5_8_r6, IN(R(6, 0x00000100u)), OUT(R(5, 0x0000007fu)), KEEP, KEEP, 0u, 1u);
	run_case("ssat16 r5,#8,r6 b", ENC_ssat16_r5_8_r6, IN(R(6, 0x0100ff00u)), OUT(R(5, 0x007fff80u)), KEEP, KEEP, 0u, 1u);
	run_case("ssat16 r5,#8,r6 c", ENC_ssat16_r5_8_r6, IN(R(6, 0x0000007fu)), OUT(R(5, 0x0000007fu)), KEEP, KEEP, 0u, 0u);
	run_case("ssat16 r5,#8,r6 d", ENC_ssat16_r5_8_r6, IN(R(6, 0xffffff80u)), OUT(R(5, 0xffffff80u)), KEEP, KEEP, 0u, 0u);
	run_case("ssat16 r5,#8,r6 e", ENC_ssat16_r5_8_r6, IN(R(6, 0x00000000u)), OUT(R(5, 0x00000000u)), KEEP, KEEP, 0u, 0u);
	run_case("ssat16 r5,#8,r6 f", ENC_ssat16_r5_8_r6, IN(R(6, 0xffffffffu)), OUT(R(5, 0xffffffffu)), KEEP, KEEP, 0u, 0u);

	/* USAT16 r0, #0, r1: every halfword to 0 */
	T1Q("usat16 #0 0", ENC_usat16_r0_0_r1, 0x00000000u, 0x00000000u, 0);
	T1Q("usat16 #0 1", ENC_usat16_r0_0_r1, 0x00000001u, 0x00000000u, 1);
	T1Q("usat16 #0 -1", ENC_usat16_r0_0_r1, 0x0000ffffu, 0x00000000u, 1);
	T1Q("usat16 #0 hi", ENC_usat16_r0_0_r1, 0x00010000u, 0x00000000u, 1);
	T1Q("usat16 #0 7fff", ENC_usat16_r0_0_r1, 0x7fff7fffu, 0x00000000u, 1);
	T1Q("usat16 #0 8000", ENC_usat16_r0_0_r1, 0x80008000u, 0x00000000u, 1);
	/* USAT16 r0, #15, r1: each halfword to [0, 32767] */
	T1Q("usat16 #15 0", ENC_usat16_r0_15_r1, 0x00000000u, 0x00000000u, 0);
	T1Q("usat16 #15 7fff", ENC_usat16_r0_15_r1, 0x7fff7fffu, 0x7fff7fffu, 0);
	T1Q("usat16 #15 8000", ENC_usat16_r0_15_r1, 0x80008000u, 0x00000000u, 1);
	T1Q("usat16 #15 ffff", ENC_usat16_r0_15_r1, 0xffffffffu, 0x00000000u, 1);
	T1Q("usat16 #15 mix", ENC_usat16_r0_15_r1, 0x80007fffu, 0x00007fffu, 1);
	T1Q("usat16 #15 mix2", ENC_usat16_r0_15_r1, 0x7fff0000u, 0x7fff0000u, 0);

	/* Q is sticky: a saturating instruction with Q already set leaves it set */
	run_case("ssat sticky", ENC_ssat_r0_16_r1, IN(R(1, 0x00008000u)), OUT(R(0, 0x00007fffu)),
	         KEEP, KEEP, 1u, 1u);
	/* ... and a non-saturating one does not clear it either */
	run_case("ssat keep q", ENC_ssat_r0_16_r1, IN(R(1, 0x00000001u)), OUT(R(0, 0x00000001u)),
	         KEEP, KEEP, 1u, 1u);
}

/* ------------------------------------------------------------------------------------ */
/* PKHBT PKHTB SEL                                                                      */
/* ------------------------------------------------------------------------------------ */
static void test_pkh_sel(void)
{
	/* PKHBT with LSL #0 */
	T2("pkhbt 0", ENC_pkhbt_r0_r1_r2, 0x11112222u, 0x33334444u, 0x33332222u);
	T2("pkhbt all", ENC_pkhbt_r0_r1_r2, 0xffffffffu, 0x00000000u, 0x0000ffffu);
	T2("pkhbt all2", ENC_pkhbt_r0_r1_r2, 0x00000000u, 0xffffffffu, 0xffff0000u);
	T2("pkhbt mix", ENC_pkhbt_r0_r1_r2, 0xdeadbeefu, 0x12345678u, 0x1234beefu);
	T2("pkhbt hi", ENC_pkhbt_r0_r1_r2, 0x7fffffffu, 0x80000000u, 0x8000ffffu);
	T2("pkhbt 8000", ENC_pkhbt_r0_r1_r2, 0x00008000u, 0x00008000u, 0x00008000u);
	/* PKHBT with LSL #8 */
	T2("pkhbt lsl8", ENC_pkhbt_r0_r1_r2_lsl8, 0x11112222u, 0x0000aaaau, 0x00aa2222u);
	T2("pkhbt lsl8 b", ENC_pkhbt_r0_r1_r2_lsl8, 0x00000000u, 0x000000ffu, 0x00000000u);
	T2("pkhbt lsl8 c", ENC_pkhbt_r0_r1_r2_lsl8, 0x00000000u, 0x00ff0000u, 0xff000000u);
	T2("pkhbt lsl8 d", ENC_pkhbt_r0_r1_r2_lsl8, 0xffffffffu, 0xffffffffu, 0xffffffffu);
	T2("pkhbt lsl8 e", ENC_pkhbt_r0_r1_r2_lsl8, 0x1234abcdu, 0x00001234u, 0x0012abcdu);
	T2("pkhbt lsl8 f", ENC_pkhbt_r0_r1_r2_lsl8, 0x00000000u, 0x80000000u, 0x00000000u);
	/* PKHBT with LSL #31 */
	T2("pkhbt lsl31", ENC_pkhbt_r0_r1_r2_lsl31, 0x11112222u, 0x00000001u, 0x80002222u);
	T2("pkhbt lsl31 b", ENC_pkhbt_r0_r1_r2_lsl31, 0x00000000u, 0x00000003u, 0x80000000u);
	T2("pkhbt lsl31 c", ENC_pkhbt_r0_r1_r2_lsl31, 0x0000ffffu, 0x00000000u, 0x0000ffffu);
	T2("pkhbt lsl31 d", ENC_pkhbt_r0_r1_r2_lsl31, 0x00000000u, 0xffffffffu, 0x80000000u);
	T2("pkhbt lsl31 e", ENC_pkhbt_r0_r1_r2_lsl31, 0xabcd0000u, 0x80000000u, 0x00000000u);
	T2("pkhbt lsl31 f", ENC_pkhbt_r0_r1_r2_lsl31, 0x12345678u, 0x40000000u, 0x00005678u);
	/* PKHTB with ASR #32 (the "no shift" form) */
	T2("pkhtb 0", ENC_pkhtb_r0_r1_r2_asr32, 0x11112222u, 0x00000000u, 0x11110000u);
	T2("pkhtb 0b", ENC_pkhtb_r0_r1_r2_asr32, 0x11112222u, 0xffffffffu, 0x1111ffffu);
	T2("pkhtb 0c", ENC_pkhtb_r0_r1_r2_asr32, 0x00000000u, 0x00008000u, 0x00000000u);
	T2("pkhtb 0d", ENC_pkhtb_r0_r1_r2_asr32, 0xdeadbeefu, 0x80000000u, 0xdeadffffu);
	T2("pkhtb 0e", ENC_pkhtb_r0_r1_r2_asr32, 0xffffffffu, 0x7fffffffu, 0xffff0000u);
	T2("pkhtb 0f", ENC_pkhtb_r0_r1_r2_asr32, 0x12345678u, 0x00000001u, 0x12340000u);
	/* PKHTB with ASR #8 */
	T2("pkhtb asr8", ENC_pkhtb_r0_r1_r2_asr8, 0x11112222u, 0x0000ab00u, 0x111100abu);
	T2("pkhtb asr8 b", ENC_pkhtb_r0_r1_r2_asr8, 0x00000000u, 0x12345678u, 0x00003456u);
	T2("pkhtb asr8 c", ENC_pkhtb_r0_r1_r2_asr8, 0xffff0000u, 0xffffffffu, 0xffffffffu);
	T2("pkhtb asr8 d", ENC_pkhtb_r0_r1_r2_asr8, 0xabcd0000u, 0x000000ffu, 0xabcd0000u);
	T2("pkhtb asr8 e", ENC_pkhtb_r0_r1_r2_asr8, 0x00000000u, 0x80000000u, 0x00000000u);
	T2("pkhtb asr8 f", ENC_pkhtb_r0_r1_r2_asr8, 0x55556666u, 0x00010000u, 0x55550100u);
	/* PKHTB with ASR #16 (op2 = 1101: bit 7 is imm5<4>, bit 6 is TB) */
	T2("pkhtb asr16", ENC_pkhtb_r0_r1_r2_asr16, 0x11112222u, 0x0000ab00u, 0x11110000u);
	T2("pkhtb asr16 b", ENC_pkhtb_r0_r1_r2_asr16, 0x00000000u, 0x12345678u, 0x00001234u);
	T2("pkhtb asr16 c", ENC_pkhtb_r0_r1_r2_asr16, 0xffff0000u, 0xffffffffu, 0xffffffffu);
	T2("pkhtb asr16 d", ENC_pkhtb_r0_r1_r2_asr16, 0xabcd0000u, 0x0000fffeu, 0xabcd0000u);
	T2("pkhtb asr16 e", ENC_pkhtb_r0_r1_r2_asr16, 0x00000000u, 0x80000000u, 0x00008000u);
	T2("pkhtb asr16 f", ENC_pkhtb_r0_r1_r2_asr16, 0x55556666u, 0x00000100u, 0x55550000u);
	T2("pkhbt lsl16", ENC_pkhbt_r0_r1_r2_lsl16, 0x11112222u, 0x00000003u, 0x00032222u);
	T2("pkhbt lsl16 b", ENC_pkhbt_r0_r1_r2_lsl16, 0x00000000u, 0x0000ffffu, 0xffff0000u);
	T2("pkhbt lsl16 c", ENC_pkhbt_r0_r1_r2_lsl16, 0xffff0000u, 0x0000ffffu, 0xffff0000u);
	T2("pkhbt lsl16 d", ENC_pkhbt_r0_r1_r2_lsl16, 0x12345678u, 0x0000abcdu, 0xabcd5678u);
	T2("pkhbt lsl16 e", ENC_pkhbt_r0_r1_r2_lsl16, 0x00000000u, 0x00010000u, 0x00000000u);
	T2("pkhbt lsl16 f", ENC_pkhbt_r0_r1_r2_lsl16, 0x0000ffffu, 0x0000ffffu, 0xffffffffu);
	/* PKHTB with ASR #32 */
	T2("pkhtb asr32", ENC_pkhtb_r0_r1_r2_asr32, 0x11112222u, 0x00000000u, 0x11110000u);
	T2("pkhtb asr32 b", ENC_pkhtb_r0_r1_r2_asr32, 0x11112222u, 0x80000000u, 0x1111ffffu);
	T2("pkhtb asr32 c", ENC_pkhtb_r0_r1_r2_asr32, 0x11112222u, 0x7fffffffu, 0x11110000u);
	T2("pkhtb asr32 d", ENC_pkhtb_r0_r1_r2_asr32, 0xdeadbeefu, 0xffffffffu, 0xdeadffffu);
	T2("pkhtb asr32 e", ENC_pkhtb_r0_r1_r2_asr32, 0x00000000u, 0xfffffffeu, 0x0000ffffu);
	T2("pkhtb asr32 f", ENC_pkhtb_r0_r1_r2_asr32, 0x12340000u, 0x00000001u, 0x12340000u);

	/* SEL: byte i comes from r1 when GE[i] is set, else from r2 */
	run_case("sel ge0", ENC_sel_r0_r1_r2, IN(R(1, 0x11223344u), R(2, 0xaabbccddu)),
	         OUT(R(0, 0xaabbccddu)), 0x0u, 0x0u, 0u, 0u);
	run_case("sel geF", ENC_sel_r0_r1_r2, IN(R(1, 0x11223344u), R(2, 0xaabbccddu)),
	         OUT(R(0, 0x11223344u)), 0xfu, 0xfu, 0u, 0u);
	run_case("sel ge5", ENC_sel_r0_r1_r2, IN(R(1, 0x11223344u), R(2, 0xaabbccddu)),
	         OUT(R(0, 0xaa22cc44u)), 0x5u, 0x5u, 0u, 0u);
	run_case("sel geA", ENC_sel_r0_r1_r2, IN(R(1, 0x11223344u), R(2, 0xaabbccddu)),
	         OUT(R(0, 0x11bb33ddu)), 0xau, 0xau, 0u, 0u);
	run_case("sel ge3", ENC_sel_r0_r1_r2, IN(R(1, 0x11223344u), R(2, 0xaabbccddu)),
	         OUT(R(0, 0xaabb3344u)), 0x3u, 0x3u, 0u, 0u);
	run_case("sel geC", ENC_sel_r0_r1_r2, IN(R(1, 0x11223344u), R(2, 0xaabbccddu)),
	         OUT(R(0, 0x1122ccddu)), 0xcu, 0xcu, 0u, 0u);
	/* field placement: SEL r5, r6, r7 with GE = 0b1010 */
	run_case("sel r5,r6,r7", ENC_sel_r5_r6_r7, IN(R(6, 0x11223344u), R(7, 0xaabbccddu)),
	         OUT(R(5, 0x11bb33ddu)), 0xau, 0xau, 0u, 0u);
}

/* ------------------------------------------------------------------------------------ */
/* parallel add/sub: SADD16 SASX SSAX SSUB16 SADD8 SSUB8 (GE written)                    */
/* ------------------------------------------------------------------------------------ */
static void test_parallel_s(void)
{
	/* SADD16: GE[i] = exact signed lane sum >= 0 (halfword lanes share GE pairs) */
	T2G("sadd16 1", ENC_sadd16_r0_r1_r2, 0x00010002u, 0x00030004u, 0x00040006u, 0xfu);
	T2G("sadd16 2", ENC_sadd16_r0_r1_r2, 0x7fff7fffu, 0x00010001u, 0x80008000u, 0xfu);
	T2G("sadd16 3", ENC_sadd16_r0_r1_r2, 0xffff0000u, 0x00000000u, 0xffff0000u, 0x3u);
	T2G("sadd16 4", ENC_sadd16_r0_r1_r2, 0xffff0001u, 0x00010001u, 0x00000002u, 0xfu);
	T2G("sadd16 5", ENC_sadd16_r0_r1_r2, 0x80008000u, 0x80008000u, 0x00000000u, 0x0u);
	T2G("sadd16 6", ENC_sadd16_r0_r1_r2, 0xdeadbeefu, 0x12345678u, 0xf0e11567u, 0x3u);
	/* SASX: lo = a.lo + b.hi, hi = a.hi - b.lo */
	T2G("sasx 1", ENC_sasx_r0_r1_r2, 0x00010002u, 0x00030004u, 0xfffd0005u, 0x3u);
	T2G("sasx 2", ENC_sasx_r0_r1_r2, 0x00000000u, 0x00010001u, 0xffff0001u, 0x3u);
	T2G("sasx 3", ENC_sasx_r0_r1_r2, 0x7fff0000u, 0x00008000u, 0xffff0000u, 0xfu);
	T2G("sasx 4", ENC_sasx_r0_r1_r2, 0xffff0000u, 0x0000ffffu, 0x00000000u, 0xfu);
	T2G("sasx 5", ENC_sasx_r0_r1_r2, 0x80008000u, 0x80008000u, 0x00000000u, 0xcu);
	T2G("sasx 6", ENC_sasx_r0_r1_r2, 0x1234deadu, 0xdead1234u, 0x0000bd5au, 0xcu);
	/* SSAX: lo = a.lo - b.hi, hi = a.hi + b.lo */
	T2G("ssax 1", ENC_ssax_r0_r1_r2, 0x00010002u, 0x00030004u, 0x0005ffffu, 0xcu);
	T2G("ssax 2", ENC_ssax_r0_r1_r2, 0x00050005u, 0x00020002u, 0x00070003u, 0xfu);
	T2G("ssax 3", ENC_ssax_r0_r1_r2, 0x80000000u, 0x80010001u, 0x80017fffu, 0x3u);
	T2G("ssax 4", ENC_ssax_r0_r1_r2, 0x00000000u, 0xffffffffu, 0xffff0001u, 0x3u);
	T2G("ssax 5", ENC_ssax_r0_r1_r2, 0x7fff7fffu, 0x80008000u, 0xffffffffu, 0x3u);
	T2G("ssax 6", ENC_ssax_r0_r1_r2, 0x11112222u, 0x33334444u, 0x5555eeefu, 0xcu);
	/* SSUB16 */
	T2G("ssub16 1", ENC_ssub16_r0_r1_r2, 0x00050003u, 0x00020001u, 0x00030002u, 0xfu);
	T2G("ssub16 2", ENC_ssub16_r0_r1_r2, 0x00000000u, 0x00000001u, 0x0000ffffu, 0xcu);
	T2G("ssub16 3", ENC_ssub16_r0_r1_r2, 0x80008000u, 0x7fff7fffu, 0x00010001u, 0x0u);
	T2G("ssub16 4", ENC_ssub16_r0_r1_r2, 0x7fff7fffu, 0x80008000u, 0xffffffffu, 0xfu);
	T2G("ssub16 5", ENC_ssub16_r0_r1_r2, 0xdeadbeefu, 0xdeadbeefu, 0x00000000u, 0xfu);
	T2G("ssub16 6", ENC_ssub16_r0_r1_r2, 0x12345678u, 0x87654321u, 0x8acf1357u, 0xfu);
	/* SADD8: one GE bit per byte, GE[i] = signed lane sum >= 0 */
	T2G("sadd8 1", ENC_sadd8_r0_r1_r2, 0x01020304u, 0x05060708u, 0x06080a0cu, 0xfu);
	T2G("sadd8 2", ENC_sadd8_r0_r1_r2, 0x7f7f7f7fu, 0x01010101u, 0x80808080u, 0xfu);
	T2G("sadd8 3", ENC_sadd8_r0_r1_r2, 0xffffffffu, 0x01010101u, 0x00000000u, 0xfu);
	T2G("sadd8 4", ENC_sadd8_r0_r1_r2, 0x80ff8000u, 0x00010001u, 0x80008001u, 0x5u);
	T2G("sadd8 5", ENC_sadd8_r0_r1_r2, 0xdeadbeefu, 0x00000000u, 0xdeadbeefu, 0x0u);
	T2G("sadd8 6", ENC_sadd8_r0_r1_r2, 0x00000000u, 0x80808080u, 0x80808080u, 0x0u);
	/* SSUB8 */
	T2G("ssub8 1", ENC_ssub8_r0_r1_r2, 0x05060708u, 0x01010101u, 0x04050607u, 0xfu);
	T2G("ssub8 2", ENC_ssub8_r0_r1_r2, 0x00000000u, 0x01010101u, 0xffffffffu, 0x0u);
	T2G("ssub8 3", ENC_ssub8_r0_r1_r2, 0x7f000000u, 0x80000000u, 0xff000000u, 0xfu);
	T2G("ssub8 4", ENC_ssub8_r0_r1_r2, 0x80008000u, 0x80008000u, 0x00000000u, 0xfu);
	T2G("ssub8 5", ENC_ssub8_r0_r1_r2, 0x000000ffu, 0x00000001u, 0x000000feu, 0xeu);
	T2G("ssub8 6", ENC_ssub8_r0_r1_r2, 0x12345678u, 0x11111111u, 0x01234567u, 0xfu);
	/* field placement: SADD16 r5, r6, r7 */
	run_case("sadd16 r5,r6,r7", ENC_sadd16_r5_r6_r7, IN(R(6, 0x00010002u), R(7, 0x00030004u)),
	         OUT(R(5, 0x00040006u)), KEEP, 0xfu, 0u, 0u);
	/* SP as the first source is legal in A32 */
	run_case("sadd16 r0,sp,r2", ENC_sadd16_r0_r13_r2, IN(R(13, 0x00010002u), R(2, 0x00030004u)),
	         OUT(R(0, 0x00040006u)), KEEP, 0xfu, 0u, 0u);
}

