/* ------------------------------------------------------------------------------------ */
/* encodings the class must reject (N2A32_UNDEF) and PC/SP operand rules                 */
/*                                                                                      */
/* Words are either produced by llvm-mc (ENC_*) or derived from one by substituting a    */
/* single field; each derivation is commented.  No word is typed in by hand.            */
/* ------------------------------------------------------------------------------------ */
static void test_undef(void)
{
	/* instructions of other classes: if the core ever routes one here it must be
	 * rejected rather than executed */
	expect_undef("mul", ENC_mul_r0_r1_r2);
	expect_undef("and", ENC_and_r0_r1_r2);
	expect_undef("ldr", ENC_ldr_r0_r1_0);
	expect_undef("bx", ENC_bx_r1);
	expect_undef("mla", ENC_mla_r0_r1_r2_r3);
	expect_undef("smull", ENC_smull_r0_r1_r2_r3);
	expect_undef("clz", ENC_clz_r0_r1);
	expect_undef("movw", ENC_movw_r0_0x1234);
	expect_undef("add", ENC_add_r0_r1_r2);
	expect_undef("mrs", ENC_mrs_r0_apsr);
	/* 16-bit T32 words never reach this class */
	expect_undef("t16 bf00", 0x0000bf00u);
	expect_undef("t16 bx lr", 0x00004770u);

	/* r15 is not a legal operand of any instruction here */
	expect_undef("sxtb r0,pc", (ENC_sxtb_r0_r1 & ~0x0000000fu) | 0x0000000fu);
	expect_undef("sxtb pc,r1", (ENC_sxtb_r0_r1 & ~0x0000f000u) | 0x0000f000u);
	expect_undef("sadd16 r0,pc,r2", (ENC_sadd16_r0_r1_r2 & ~0x000f0000u) | 0x000f0000u);
	expect_undef("sadd16 r0,r1,pc", (ENC_sadd16_r0_r1_r2 & ~0x0000000fu) | 0x0000000fu);
	expect_undef("qadd r0,r1,pc", (ENC_qadd_r0_r1_r2 & ~0x000f0000u) | 0x000f0000u);
	expect_undef("smlabb ra=pc", (ENC_smlabb_r0_r1_r2_r3 & ~0x0000f000u) | 0x0000f000u);
	expect_undef("smlalbb rdhi=pc", (ENC_smlalbb_r0_r1_r2_r3 & ~0x000f0000u) | 0x000f0000u);
	expect_undef("ssat pc,r1", (ENC_ssat_r0_16_r1 & ~0x0000f000u) | 0x0000f000u);

	/* 0110 group: fields that are fixed by the encoding */
	expect_undef("sadd16 [11:8]!=f", ENC_sadd16_r0_r1_r2 & ~0x00000100u);
	expect_undef("sadd16 [23:20]=9", ENC_sadd16_r0_r1_r2 | (8u << 20));
	expect_undef("sadd16 [23:20]=0", ENC_sadd16_r0_r1_r2 & ~0x00f00000u);
	expect_undef("sadd16 [23:20]=4", (ENC_sadd16_r0_r1_r2 & ~0x00f00000u) | (4u << 20));
	expect_undef("sadd16 op2=2", (ENC_sadd16_r0_r1_r2 & ~0x000000f0u) | 0x00000020u);
	expect_undef("sadd16 op2=0", ENC_sadd16_r0_r1_r2 & ~0x000000f0u);
	expect_undef("sxtb [9:8]!=0", ENC_sxtb_r0_r1 | 0x00000100u);
	expect_undef("sxtb [23:20]=9", (ENC_sxtb_r0_r1 & ~0x00f00000u) | (9u << 20));
	expect_undef("sxtb [23:20]=d", (ENC_sxtb_r0_r1 & ~0x00f00000u) | (0xdu << 20));
	expect_undef("ssat bit5", ENC_ssat_r0_16_r1 | 0x00000020u);
	expect_undef("rev rn!=pc", (ENC_rev_r0_r1 & ~0x000f0000u) | 0x00010000u);
	expect_undef("sel [23:20]=9", (ENC_sel_r0_r1_r2 & ~0x00f00000u) | (9u << 20));
	expect_undef("ssat16 [11:8]!=f", ENC_ssat16_r0_16_r1 & ~0x00000100u);

	/* 0111 group */
	expect_undef("smlad op2=9", ENC_smlad_r0_r1_r2_r3 | 0x00000080u);
	expect_undef("smlad op2=0", ENC_smlad_r0_r1_r2_r3 & ~0x00000010u);
	expect_undef("sdiv op2=3", ENC_sdiv_r0_r1_r2 | 0x00000020u);
	expect_undef("sdiv ra!=f", ENC_sdiv_r0_r1_r2 & ~0x00001000u);
	expect_undef("smmul op2=5", ENC_smmul_r0_r1_r2 | 0x00000040u);
	expect_undef("usad8 op2=3", ENC_usad8_r0_r1_r2 | 0x00000020u);
	expect_undef("usad8 op=9", ENC_usad8_r0_r1_r2 | (1u << 20));
	expect_undef("smlalxy rdlo=rdhi", (ENC_smlalbb_r0_r1_r2_r3 & ~0x0000f000u) | 0x00001000u);
	expect_undef("smlald rdhi=rdlo", (ENC_smlald_r0_r1_r2_r3 & ~0x0000f000u) | 0x00001000u);
	expect_undef("smlsld rdhi=pc", (ENC_smlsld_r0_r1_r2_r3 & ~0x000f0000u) | 0x000f0000u);
	expect_undef("smlald rdlo=pc", (ENC_smlald_r0_r1_r2_r3 & ~0x0000f000u) | 0x0000f000u);
	expect_undef("bitfield op=2", (ENC_sdiv_r0_r1_r2 & ~0x00f00000u) | (2u << 20));
	expect_undef("ubfx [6:5]=00", ENC_ubfx_r0_r1_4_8 & ~0x00000040u);
	expect_undef("bfi [6:5]=10", ENC_bfi_r0_r1_4_8 | 0x00000040u);
	expect_undef("ubfx lsb+width", ENC_ubfx_r0_r1_31_1 | 0x00010000u);
	expect_undef("bfi msb<lsb", (ENC_bfi_r0_r1_4_8 & ~0x00000f80u) | (20u << 7));
	expect_undef("bfc msb<lsb", (ENC_bfc_r0_4_8 & ~0x00000f80u) | (20u << 7));

	/* 0001 group */
	expect_undef("qadd [11:4]!=05", ENC_qadd_r0_r1_r2 | 0x00000020u);
	expect_undef("smulbb op2=9", ENC_smulbb_r0_r1_r2 | 0x00000010u);
	expect_undef("smulbb op=11", ENC_smulbb_r0_r1_r2 | (1u << 20));
	expect_undef("smulbb [15:12]!=0", ENC_smulbb_r0_r1_r2 | 0x00001000u);
	expect_undef("smulwb [15:12]!=0", ENC_smulwb_r0_r1_r2 | 0x00001000u);
	expect_undef("smlabb ra=pc (2)", (ENC_smlabb_r0_r1_r2_r3 & ~0x0000f000u) | 0x0000f000u);
}

static void test_other_operands(void)
{
	/* r13 (SP) is legal in A32 for these instructions */
	run_case("qadd r0,r1,sp", (ENC_qadd_r0_r1_r2 & ~0x000f0000u) | 0x000d0000u,
	         IN(R(1, 5u), R(13, 7u)), OUT(R(0, 12u)), KEEP, KEEP, 0u, 0u);
	run_case("smlabb ra=sp", (ENC_smlabb_r0_r1_r2_r3 & ~0x0000f000u) | 0x0000d000u,
	         IN(R(1, 3u), R(2, 4u), R(13, 100u)), OUT(R(0, 112u)), KEEP, KEEP, 0u, 0u);
	run_case("sel sp source", (ENC_sel_r0_r1_r2 & ~0x000f0000u) | 0x000d0000u,
	         IN(R(13, 0x11223344u), R(2, 0xaabbccddu)), OUT(R(0, 0x1122ccddu)),
	         0xcu, 0xcu, 0u, 0u);
}

int main(void)
{
	memset(&g_mem, 0, sizeof g_mem);
	g_mem.base = (uint8_t *)calloc(1u, 16u << 20);
	if (g_mem.base == NULL) {
		printf("N2TEST V11 FAIL calloc\n");
		return 1;
	}

	test_extend();
	test_extend_add();
	test_bitfield();
	test_rev();
	test_sat();
	test_pkh_sel();
	test_parallel_s();
	test_parallel_q();
	test_parallel_sh();
	test_parallel_u();
	test_parallel_uq();
	test_parallel_uh();
	test_qadd();
	test_mul_16();
	test_mul_dual();
	test_div();
	test_other_operands();
	test_undef();
	sweep();

	free(g_mem.base);
	g_mem.base = NULL;
	if (failures != 0) {
		printf("N2TEST V11 FAIL %d/%d checks failed\n", failures, checks);
		return 1;
	}
	printf("N2TEST V11 PASS %d/%d\n", checks, checks);
	return 0;
}
